					'dataTypeId': None,
					'engUnitId': None,
					'specInfo': defaultSpec,
					'pickListInfo': defaultPickList
				}

return stepConfig

onChange.script:
system.perspective.print(origin)
if origin in ('BindingWriteback', 'Script'): self.getChild("root").updateStep()

return

transforms.code:
security = value['security']
canCreate = False
canEdit = False
if security['userCRUD'] is not None and security['userId'] is not None:
	if security['userCRUD']['isGatewayAdmin'] or security['userCRUD']['configureMaintenance']['enabled']: 
		canCreate = True
		canEdit = True

return {"canCreate": canCreate, "canDelete": canEdit, "canRead": True, "canUpdate": canEdit}

